import java.io.*;
import java.util.*;

public class D4 {
    private static final Map<Long, Long> EDGE = new HashMap<>();

    static {
        EDGE.put(2L, 0L);
        EDGE.put(3L, 4L);
        EDGE.put(7L, 12L);
    }

    public static void main(String[] args) throws Exception {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        byte[] buf = new byte[1024];
        int len;
        while ((len = System.in.read(buf)) != -1) {
            baos.write(buf, 0, len);
        }
        StringTokenizer st = new StringTokenizer(new String(baos.toByteArray(), "UTF-8"));
        long n = st.hasMoreTokens() ? Long.parseLong(st.nextToken()) : 0;
        long m = st.hasMoreTokens() ? Long.parseLong(st.nextToken()) : 0;
        System.out.println(solve(n, m));
    }

    static long solve(long n, long m) {
        long a = Math.min(n, m), b = Math.max(n, m);
        if (a == 1) {
            long base = (b / 6) * 6;
            long r = b % 6;
            if (r == 4) base += 2;
            if (r == 5) base += 4;
            return base;
        }
        if (a == 2 && EDGE.containsKey(b)) return EDGE.get(b);
        return a * b - (a % 2 == 1 && b % 2 == 1 ? 1 : 0);
    }
}
